<script setup lang="ts">
import { computed, ref } from 'vue';
import { router, useForm, usePage } from '@inertiajs/vue3';
import MemberLayout from '../../Layouts/MemberLayout.vue';
import { CalendarDays, Check, CheckCircle2, Clock3, Dumbbell, Flame, MessageCircle, Target } from '@lucide/vue';
type Profile={id:number;name:string;photo_url:string|null}; type Exercise={id:number;day_label:string|null;title:string;category:string;sets:number|null;reps:number|null;duration_minutes:number|null;rest_seconds:number|null;notes:string|null;completed:boolean};
type Plan={id:number;title:string;description:string|null;starts_on:string;ends_on:string;coach:string;target:string|null;exercises:Exercise[]};
const props=defineProps<{viewer:{mode:string};profiles:Profile[];athlete:{id:number;name:string}|null;plans:Plan[];canComplete:boolean}>(); const page=usePage();
const activePlan=ref(props.plans[0]?.id||null); const effort=ref<Record<number,number>>({});
const isGuardian=computed(()=>props.viewer.mode==='guardian'); const total=computed(()=>props.plans.reduce((n,p)=>n+p.exercises.length,0)); const done=computed(()=>props.plans.reduce((n,p)=>n+p.exercises.filter(e=>e.completed).length,0)); const percent=computed(()=>total.value?Math.round(done.value/total.value*100):0);
const categories={strength:'قدرتی',jump:'پرش',speed:'سرعت و چابکی',serve:'سرویس',reception:'دریافت',spike:'اسپک',block:'دفاع روی تور',recovery:'ریکاوری'};
const selectProfile=(id:number)=>router.get('/my-training',{athlete:id},{preserveState:false});
const toggle=(exercise:Exercise)=>router.patch(`/my-training/exercises/${exercise.id}`,{completed:!exercise.completed,effort:!exercise.completed?(effort.value[exercise.id]||3):null},{preserveScroll:true});
const dateLabel=(value:string)=>new Intl.DateTimeFormat('fa-IR',{day:'numeric',month:'long'}).format(new Date(`${value}T12:00:00`));
</script>
<template><MemberLayout title="تمرین من" :athlete-id="athlete?.id">
<section v-if="!athlete" class="member-empty"><Dumbbell :size="36"/><h2>پرونده ورزشی متصل نیست</h2><p>پس از اتصال پرونده، برنامه‌های مربی در این صفحه نمایش داده می‌شوند.</p></section>
<template v-else><div v-if="page.props.flash?.success" class="member-success"><CheckCircle2 :size="17"/>{{page.props.flash.success}}</div><section v-if="isGuardian&&profiles.length>1" class="member-profile-switch"><span>برنامه کدام ورزشکار؟</span><button v-for="profile in profiles" :key="profile.id" :class="profile.id===athlete.id?'active':''" @click="selectProfile(profile.id)"><img v-if="profile.photo_url" :src="profile.photo_url"><span v-else>{{profile.name.slice(0,1)}}</span>{{profile.name}}</button></section>
<header class="member-workout-hero"><div><span><Flame :size="16"/>برنامه فعال {{athlete.name}}</span><h1>وقت تمرینه!</h1><p>قدم‌به‌قدم برنامه مربی را انجام بده و پیشرفتت را ثبت کن.</p></div><div class="member-workout-progress"><strong>{{percent}}٪</strong><span>{{done}} از {{total}} حرکت</span><i><b :style="{width:`${percent}%`}"/></i></div></header>
<section v-if="plans.length" class="member-workout-plans"><article v-for="plan in plans" :key="plan.id" :class="{'is-open':activePlan===plan.id}"><button class="member-workout-plan-head" @click="activePlan=activePlan===plan.id?null:plan.id"><span><Dumbbell :size="20"/></span><div><small>{{plan.target}} · مربی {{plan.coach}}</small><h2>{{plan.title}}</h2><p><CalendarDays :size="12"/>{{dateLabel(plan.starts_on)}} تا {{dateLabel(plan.ends_on)}}</p></div><strong>{{plan.exercises.filter(e=>e.completed).length}}/{{plan.exercises.length}}</strong></button><div v-if="activePlan===plan.id" class="member-workout-body"><p v-if="plan.description" class="member-workout-goal"><Target :size="17"/>{{plan.description}}</p><div class="member-exercises"><article v-for="exercise in plan.exercises" :key="exercise.id" :class="{'is-done':exercise.completed}"><button class="member-exercise-check" :disabled="!canComplete" @click="toggle(exercise)"><Check :size="17"/></button><div><span>{{exercise.day_label||'برنامه اصلی'}} · {{categories[exercise.category as keyof typeof categories]}}</span><h3>{{exercise.title}}</h3><p><b v-if="exercise.sets">{{exercise.sets}} ست</b><b v-if="exercise.reps">{{exercise.reps}} تکرار</b><b v-if="exercise.duration_minutes"><Clock3 :size="12"/>{{exercise.duration_minutes}} دقیقه</b><b v-if="exercise.rest_seconds">{{exercise.rest_seconds}} ثانیه استراحت</b></p><small v-if="exercise.notes"><MessageCircle :size="12"/>{{exercise.notes}}</small></div><label v-if="canComplete&&!exercise.completed">سختی<select v-model="effort[exercise.id]"><option :value="1">خیلی سبک</option><option :value="2">سبک</option><option :value="3">مناسب</option><option :value="4">سخت</option><option :value="5">خیلی سخت</option></select></label><em v-if="exercise.completed">انجام شد</em></article></div><p v-if="!canComplete" class="member-guardian-note">ثبت انجام تمرین فقط از حساب خود ورزشکار امکان‌پذیر است.</p></div></article></section>
<section v-else class="member-empty compact"><Dumbbell :size="31"/><h2>برنامه فعالی نداری</h2><p>به محض اینکه مربی برنامه تازه‌ای ثبت کند، اینجا و در پیام‌های باشگاه به تو اطلاع می‌دهیم.</p></section></template>
</MemberLayout></template>
